const queries=[{"name":"RETURN_RESERVATION_CONFLICTS","sql":"SELECT o.id AS order_id,o.external_id,o.shipping_status,ret.id AS return_id,ret.return_date,ri.order_item_id,oi.product_name_snapshot,oi.stock_writeoff_status,oi.quantity AS ordered_qty,ri.quantity AS returned_qty,ri.physical_tracking,ri.physical_received_at,ri.inventory_source,ir.id AS reservation_id,ir.status AS reservation_status,ir.quantity AS reservation_qty,ir.inventory_source AS reservation_source,ir.variant_id FROM return_items ri JOIN returns ret ON ret.id=ri.return_id JOIN orders o ON o.id=ret.order_id JOIN order_items oi ON oi.id=ri.order_item_id JOIN inventory_reservations ir ON ir.order_item_id=ri.order_item_id WHERE COALESCE(ret.status,'completed') <> 'cancelled' AND NOT EXISTS(SELECT 1 FROM exchanges ex WHERE ex.refund_return_id=ret.id AND COALESCE(ex.status,'completed') <> 'cancelled') AND ri.quantity>0 AND ir.status IN ('active','unresolved') ORDER BY ret.id DESC,ir.id DESC LIMIT 100"},{"name":"CASE_1563_OR_RETURN_43","sql":"SELECT o.id AS order_id,o.external_id,o.shipping_status,o.order_status,ret.id AS return_id,ret.return_date,ret.amount AS refund_amount,ri.order_item_id,oi.product_name_snapshot,oi.source_type,oi.stock_writeoff_status,oi.quantity AS original_quantity,oi.variant_id AS order_variant_id,ri.quantity AS returned_quantity,ri.physical_tracking,ri.physical_received_at,ri.inventory_source,ir.id AS reservation_id,ir.status AS reservation_status,ir.quantity AS reservation_quantity,ir.variant_id AS reservation_variant_id FROM returns ret JOIN orders o ON o.id=ret.order_id LEFT JOIN return_items ri ON ri.return_id=ret.id LEFT JOIN order_items oi ON oi.id=ri.order_item_id LEFT JOIN inventory_reservations ir ON ir.order_item_id=ri.order_item_id WHERE o.id=1563 OR ret.id=43 ORDER BY ret.id DESC,ri.id,ir.id LIMIT 50"},{"name":"OCTOBER_RETURN_BY_SHIPPING_SNAPSHOT","sql":"WITH goods AS (SELECT ri.return_id,SUM(ri.quantity) AS goods_qty,SUM(CASE WHEN ri.physical_tracking=1 AND ri.physical_received_at IS NULL THEN ri.quantity ELSE 0 END) AS pending_qty,SUM(CASE WHEN ri.physical_tracking=1 AND ri.physical_received_at IS NOT NULL THEN ri.quantity ELSE 0 END) AS physically_received_qty FROM return_items ri GROUP BY ri.return_id), observed AS (SELECT o.shipping_status,r.id,r.amount,COALESCE(g.goods_qty,0) AS goods_qty,COALESCE(g.pending_qty,0) AS pending_qty,COALESCE(g.physically_received_qty,0) AS received_qty FROM returns r JOIN orders o ON o.id=r.order_id LEFT JOIN goods g ON g.return_id=r.id WHERE r.return_date >= '2026-10-01' AND r.return_date < '2026-11-01' AND COALESCE(r.status,'completed') <> 'cancelled' AND NOT EXISTS(SELECT 1 FROM exchanges e WHERE e.refund_return_id=r.id AND COALESCE(e.status,'completed') <> 'cancelled')) SELECT COALESCE(shipping_status,'unknown') AS shipping_status,COUNT(*) AS returns_count,SUM(CASE WHEN amount>0 AND goods_qty=0 THEN 1 ELSE 0 END) AS money_only,SUM(CASE WHEN amount>0 AND goods_qty>0 THEN 1 ELSE 0 END) AS money_plus_goods,SUM(CASE WHEN amount=0 AND goods_qty>0 THEN 1 ELSE 0 END) AS goods_only,SUM(pending_qty) AS pending_goods,SUM(received_qty) AS received_goods FROM observed GROUP BY shipping_status ORDER BY shipping_status"},{"name":"OCTOBER_MONEY_ONLY_IDENTIFIERS","sql":"SELECT ret.id AS return_id,o.id AS order_id,o.external_id,ret.return_date,ret.amount,o.shipping_status FROM returns ret JOIN orders o ON o.id=ret.order_id WHERE ret.return_date>='2026-10-01' AND ret.return_date<'2026-11-01' AND ret.amount>0 AND COALESCE(ret.status,'completed') <> 'cancelled' AND NOT EXISTS(SELECT 1 FROM return_items ri WHERE ri.return_id=ret.id AND ri.quantity>0) AND NOT EXISTS(SELECT 1 FROM exchanges ex WHERE ex.refund_return_id=ret.id AND COALESCE(ex.status,'completed') <> 'cancelled') ORDER BY ret.id LIMIT 30"},{"name":"ACTIVE_RESERVATION_SHORTAGES","sql":"WITH reserved AS (SELECT inventory_source,variant_id,SUM(quantity) AS reserved_qty,COUNT(*) AS reserve_lines FROM inventory_reservations WHERE status='active' AND variant_id IS NOT NULL AND inventory_source IN ('warehouse','boutique') GROUP BY inventory_source,variant_id) SELECT r.inventory_source,r.variant_id,r.reserved_qty,r.reserve_lines,COALESCE(s.quantity,0) AS physical_qty,r.reserved_qty-COALESCE(s.quantity,0) AS shortage_qty FROM reserved r LEFT JOIN inventory_stock s ON s.inventory_source=r.inventory_source AND s.variant_id=r.variant_id WHERE r.reserved_qty>COALESCE(s.quantity,0) ORDER BY shortage_qty DESC,r.variant_id LIMIT 80"},{"name":"PHYSICAL_RETURN_RECEIPTS","sql":"SELECT COALESCE(ri.physical_tracking,0) AS tracked,CASE WHEN ri.physical_received_at IS NULL THEN 'not_received' ELSE 'received' END AS receipt,COALESCE(ri.inventory_source,'no_stock') AS destination,COUNT(*) AS lines,SUM(ri.quantity) AS units FROM return_items ri JOIN returns r ON r.id=ri.return_id WHERE COALESCE(r.status,'completed')<>'cancelled' AND NOT EXISTS(SELECT 1 FROM exchanges e WHERE e.refund_return_id=r.id AND COALESCE(e.status,'completed')<>'cancelled') GROUP BY 1,2,3 ORDER BY 1,2,3"},{"name":"RETURN_43_LIFECYCLE","sql":"SELECT id,operation_type,operation_id,order_item_id,event_type,direction,inventory_source,variant_id,quantity,status,applied_at,created_at FROM inventory_lifecycle_events WHERE operation_type='return' AND operation_id=43 ORDER BY id LIMIT 30"}]
queries.push(...[{"name":"CASE_1563_RESERVATION_HISTORY","sql":"SELECT ir.id,ir.order_id,ir.order_item_id,ir.inventory_source,ir.variant_id,ir.quantity,ir.status,ir.unresolved_reason,ir.created_at,ir.updated_at,ir.fulfilled_at,ir.released_at,oi.stock_writeoff_status,oi.created_at AS item_created_at FROM inventory_reservations ir JOIN order_items oi ON oi.id=ir.order_item_id WHERE ir.order_id=1563 ORDER BY ir.id"},{"name":"CASE_1563_STOCK_POSITIONS","sql":"SELECT inventory_source,variant_id,quantity,reserved_quantity,last_action,last_source_ref,updated_at FROM inventory_stock WHERE variant_id IN (212,1444,853,1302,1437) ORDER BY variant_id,inventory_source"},{"name":"CASE_1563_MOVEMENT_TIMELINE","sql":"SELECT id,created_at,inventory_source,variant_id,movement_type,quantity_delta,quantity_after,reference_type,reference_id FROM inventory_movements WHERE variant_id IN (212,1444,853,1302,1437) AND created_at>='2026-09-01' ORDER BY created_at DESC,id DESC LIMIT 100"},{"name":"SHORTAGE_ORDER_REFERENCES","sql":"WITH shortage AS (SELECT r.inventory_source,r.variant_id,SUM(r.quantity) AS reserved_qty FROM inventory_reservations r WHERE r.status='active' AND r.variant_id IS NOT NULL AND r.inventory_source IN ('warehouse','boutique') GROUP BY r.inventory_source,r.variant_id HAVING SUM(r.quantity)>COALESCE((SELECT s.quantity FROM inventory_stock s WHERE s.variant_id=r.variant_id AND s.inventory_source=r.inventory_source LIMIT 1),0)) SELECT short.inventory_source,short.variant_id,o.id AS order_id,o.external_id,ir.order_item_id,oi.product_name_snapshot,oi.stock_writeoff_status,ir.quantity,oi.source_type,ir.created_at,ir.updated_at FROM shortage short JOIN inventory_reservations ir ON ir.inventory_source=short.inventory_source AND ir.variant_id=short.variant_id AND ir.status='active' JOIN orders o ON o.id=ir.order_id JOIN order_items oi ON oi.id=ir.order_item_id ORDER BY short.variant_id,o.id LIMIT 100"},{"name":"CASE_1563_RETURN_46_LIFECYCLE","sql":"SELECT id,operation_type,operation_id,order_item_id,event_type,inventory_source,variant_id,quantity,status,applied_at,created_at FROM inventory_lifecycle_events WHERE operation_type='return' AND operation_id=46 ORDER BY id"}])
queries.push(...[{"name":"ATTENTION_SHIPPED_EVIDENCE_COUNTS","sql":"SELECT COUNT(*) AS all_shipping_evidence,SUM(CASE WHEN e.unexplained_quantity>0 THEN 1 ELSE 0 END) AS unexplained_shipping_rows,SUM(CASE WHEN e.unexplained_quantity>0 AND o.shipping_status='sent' AND COALESCE(o.order_status,'active')<>'deleted' THEN 1 ELSE 0 END) AS shown_as_open_shortages,SUM(CASE WHEN e.unexplained_quantity>0 AND o.shipping_status='sent' AND COALESCE(o.order_status,'active')<>'deleted' AND EXISTS (SELECT 1 FROM inventory_stock_checks c WHERE c.inventory_source=e.inventory_source AND c.variant_id=e.variant_id AND c.checked_at>e.occurred_at) THEN 1 ELSE 0 END) AS after_exact_physical_check,SUM(CASE WHEN e.unexplained_quantity>0 AND o.shipping_status='sent' AND COALESCE(o.order_status,'active')<>'deleted' AND EXISTS (SELECT 1 FROM inventory_stocktake_sessions s WHERE s.inventory_source=e.inventory_source AND s.status='completed' AND s.completed_at>e.occurred_at AND s.id NOT LIKE 'REV-%-P-%') THEN 1 ELSE 0 END) AS after_full_stocktake FROM inventory_operation_evidence e LEFT JOIN orders o ON o.external_id=e.operation_reference WHERE e.operation_type='shipping'"},{"name":"ATTENTION_SHIPPED_EVIDENCE_AGE","sql":"SELECT SUBSTR(e.occurred_at,1,7) AS event_month,COUNT(*) AS evidence_rows,SUM(e.unexplained_quantity) AS untracked_units,COUNT(DISTINCT e.operation_reference) AS orders FROM inventory_operation_evidence e JOIN orders o ON o.external_id=e.operation_reference WHERE e.operation_type='shipping' AND e.unexplained_quantity>0 AND o.shipping_status='sent' AND COALESCE(o.order_status,'active')<>'deleted' GROUP BY SUBSTR(e.occurred_at,1,7) ORDER BY event_month DESC LIMIT 18"},{"name":"ATTENTION_SHIPPED_CURRENT_BALANCE","sql":"SELECT COUNT(*) AS events,SUM(CASE WHEN COALESCE(s.quantity,0)<0 THEN 1 ELSE 0 END) AS negative_physical,SUM(CASE WHEN COALESCE(s.quantity,0)=0 THEN 1 ELSE 0 END) AS zero_physical,SUM(CASE WHEN COALESCE(s.quantity,0)>0 THEN 1 ELSE 0 END) AS positive_physical,SUM(CASE WHEN COALESCE(s.quantity,0) < COALESCE(s.reserved_quantity,0) THEN 1 ELSE 0 END) AS current_reserve_gap FROM inventory_operation_evidence e JOIN orders o ON o.external_id=e.operation_reference LEFT JOIN inventory_stock s ON s.inventory_source=e.inventory_source AND s.variant_id=e.variant_id WHERE e.operation_type='shipping' AND e.unexplained_quantity>0 AND o.shipping_status='sent' AND COALESCE(o.order_status,'active')<>'deleted'"},{"name":"ATTENTION_SHIPPED_SAMPLES","sql":"SELECT e.id AS evidence_id,e.occurred_at,e.inventory_source,e.variant_id,e.tracked_physical_before,e.confirmed_operation_quantity,e.unexplained_quantity,o.id AS order_id,o.order_date,o.shipping_status,COALESCE(s.quantity,0) AS now_physical,COALESCE(s.reserved_quantity,0) AS now_reserved,(SELECT MAX(c.checked_at) FROM inventory_stock_checks c WHERE c.inventory_source=e.inventory_source AND c.variant_id=e.variant_id AND c.checked_at>e.occurred_at) AS later_physical_check FROM inventory_operation_evidence e JOIN orders o ON o.external_id=e.operation_reference LEFT JOIN inventory_stock s ON s.inventory_source=e.inventory_source AND s.variant_id=e.variant_id WHERE e.operation_type='shipping' AND e.unexplained_quantity>0 AND o.shipping_status='sent' AND COALESCE(o.order_status,'active')<>'deleted' ORDER BY e.occurred_at DESC,e.id DESC LIMIT 20"}])
queries.push(...[{"name":"ATTENTION_SHIPPED_EVIDENCE_HISTORY_COVERAGE","sql":"SELECT COUNT(*) AS old_shipping_events,SUM(CASE WHEN EXISTS (SELECT 1 FROM inventory_movements m WHERE m.inventory_source=e.inventory_source AND m.variant_id=e.variant_id AND m.reference_id=e.operation_reference AND m.movement_type='sale') THEN 1 ELSE 0 END) AS linked_sale_movements,SUM(CASE WHEN NOT EXISTS (SELECT 1 FROM inventory_movements m WHERE m.inventory_source=e.inventory_source AND m.variant_id=e.variant_id AND m.reference_id=e.operation_reference AND m.movement_type='sale') THEN 1 ELSE 0 END) AS without_sale_movement FROM inventory_operation_evidence e JOIN orders o ON o.external_id=e.operation_reference WHERE e.operation_type='shipping' AND e.unexplained_quantity>0 AND o.shipping_status='sent' AND COALESCE(o.order_status,'active')<>'deleted'"}])
queries.push(...[{"name":"RESOLVER_SCREENSHOT_ORDER_ROWS","sql":"SELECT oi.id AS item_id,oi.order_id,o.external_id,o.order_date,o.shipping_status,o.order_status,oi.product_id,oi.variant_id,oi.product_name_snapshot,oi.audience_type,oi.gender_snapshot,oi.color_snapshot,oi.material_snapshot,oi.length_snapshot,oi.size_snapshot,oi.quantity,oi.is_workshop,oi.stock_writeoff_status,oi.source_type,oi.created_at FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.order_date BETWEEN '2026-10-06' AND '2026-10-19' AND (UPPER(oi.product_name_snapshot) LIKE '%ҚОЗЫ%' OR UPPER(oi.product_name_snapshot) LIKE '%АЙ-Н%' OR UPPER(oi.product_name_snapshot) LIKE '%АЙДАР%' OR UPPER(oi.product_name_snapshot) LIKE '%АЙНҰР%' OR UPPER(oi.product_name_snapshot) LIKE '%СЕРТИФИКАТ%') ORDER BY oi.id DESC LIMIT 180"},{"name":"RESOLVER_SCREENSHOT_CATALOG_PRODUCTS","sql":"SELECT p.id,p.name,p.category,p.gender_scope,p.is_active,(SELECT COUNT(*) FROM catalog_variants v WHERE v.product_id=p.id AND v.is_active=1) AS active_skus FROM catalog_products p WHERE (UPPER(p.name) LIKE '%ҚОЗЫ%' OR UPPER(p.name) LIKE '%АЙ-Н%' OR UPPER(p.name) LIKE '%АЙДАР%' OR UPPER(p.name) LIKE '%АЙНҰР%' OR UPPER(p.name) LIKE '%СЕРТИФИКАТ%') ORDER BY p.name,p.id LIMIT 90"},{"name":"RESOLVER_SCREENSHOT_CATALOG_VARIANTS","sql":"SELECT v.id,v.product_id,p.name AS product_name,v.category,v.gender,v.color,v.material,v.length,v.size_label,v.is_active,v.stock_position_id FROM catalog_variants v JOIN catalog_products p ON p.id=v.product_id WHERE (UPPER(p.name) LIKE '%ҚОЗЫ%' OR UPPER(p.name) LIKE '%АЙ-Н%' OR UPPER(p.name) LIKE '%АЙДАР%' OR UPPER(p.name) LIKE '%АЙНҰР%' OR UPPER(p.name) LIKE '%СЕРТИФИКАТ%') ORDER BY p.name,v.is_active DESC,v.size_label,v.id LIMIT 240"},{"name":"RESOLVER_SCREENSHOT_REFERENCE_VALUES","sql":"SELECT kind,value,is_active FROM reference_values WHERE kind IN ('material','length','color','size','child_age') AND (UPPER(value) LIKE '%ДЖИНС%' OR UPPER(value) LIKE '%КАШЕМИР%' OR UPPER(value) LIKE '%БОРДОВ%' OR UPPER(value) LIKE '%КОРИЧ%' OR UPPER(value) LIKE '%ЧЕРН%' OR TRIM(value) IN ('6','44','50','56','БЕЗ РАЗМЕРА','СТАНДАРТ')) ORDER BY kind,value LIMIT 110"},{"name":"RESOLVER_SCREENSHOT_PRODUCT_ALIASES","sql":"SELECT a.raw_value,a.alias_key,a.product_id,p.name AS canonical_product_name,p.is_active FROM catalog_product_aliases a JOIN catalog_products p ON p.id=a.product_id WHERE UPPER(a.raw_value) LIKE '%ҚОЗЫ%' OR UPPER(a.raw_value) LIKE '%АЙ-Н%' OR UPPER(a.raw_value) LIKE '%АЙДАР%' OR UPPER(a.raw_value) LIKE '%АЙНҰР%' OR UPPER(a.raw_value) LIKE '%СЕРТИФИКАТ%' ORDER BY a.raw_value LIMIT 75"}])
for(const {name,sql} of queries){
 assert(/^\s*(?:SELECT|WITH)\b/i.test(sql)&&!sql.includes(';')&&!/\b(?:INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|REPLACE|PRAGMA|ATTACH|VACUUM|MERGE)\b/i.test(sql),'Not a read-only SELECT')
 const res=await fetch(base+'/query',{method:'POST',headers,body:JSON.stringify({sql}),signal:AbortSignal.timeout(30000)})
 const data=await res.json()
 if(!res.ok||!data.success)throw Error(name+' SELECT failed: '+JSON.stringify({status:res.status,codes:(data.errors||[]).map(e=>e.code)}))
 console.log('FORENSIC_'+name+' '+JSON.stringify(data.result?.[0]?.results||[]))
}
